using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class FluidSolverOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var result)?result:fallback;
    public void initialize(Settings state,Settings values,Vector3[] points){state["points"]=points;var velocities=new Vector3[points.Length];Array.Fill(velocities,state["v"].AsVector3());state["velocities"]=velocities;state["fluid_ids"]=Enumerable.Range(0,points.Length).ToArray();var masses=new float[points.Length];Array.Fill(masses,(float)(values["fluid_density"].AsDouble()*Math.Pow(values["spacing"].AsDouble(),3)));state["fluid_masses"]=masses;state["fluid_foam"]=new float[points.Length];var density=new float[points.Length];Array.Fill(density,1);state["fluid_density"]=density;state["fluid_next_id"]=points.Length;state["fluid_emitted"]=0;state["fluid_emit_fraction"]=0.0;state["fluid_contacts"]=new GArray();state["fluid_checks"]=0;}
    public double random(long seed)=>unchecked((seed*1103515245+12345)&0x7fffffff)/2147483648.0;
    public void emit(Settings state,Settings values,Transform3D pose,Vector3 velocity,double local,double dt)
    {
        if(values["fluid_source_mode"].AsInt32()==0)return;double start=values["fluid_emit_start"].AsDouble(),end=values["fluid_emit_end"].AsDouble(),duration=Math.Max(0,Math.Min(local,end>=0?end:local)-Math.Max(start,local-dt));if(duration<=0)return;double fraction=state["fluid_emit_fraction"].AsDouble()+values["fluid_emit_rate"].AsDouble()*duration;var oldPoints=state["points"].AsVector3Array();int count=Math.Min((int)Math.Floor(fraction),values["budget"].AsInt32()-oldPoints.Length);state["fluid_emit_fraction"]=fraction-Math.Floor(fraction);if(values["fluid_supply"].AsInt32()>0)count=Math.Min(count,Math.Max(0,values["fluid_supply"].AsInt32()-state["fluid_emitted"].AsInt32()));if(count<=0)return;int length=oldPoints.Length,total=length+count;var points=Resize(oldPoints,total);var velocities=Resize(state["velocities"].AsVector3Array(),total);var ids=Resize(state["fluid_ids"].AsInt32Array(),total);var masses=Resize(state["fluid_masses"].AsFloat32Array(),total);var foam=Resize(state["fluid_foam"].AsFloat32Array(),total);var density=Resize(state["fluid_density"].AsFloat32Array(),total);var axis=values["fluid_emit_direction"].AsVector3().Normalized();if(axis.IsZeroApprox())axis=Vector3.Down;var tangent=axis.Cross(Math.Abs(axis.X)<.9?Vector3.Right:Vector3.Up).Normalized();var bitangent=axis.Cross(tangent);long next=state["fluid_next_id"].AsInt64();double radius=values["fluid_emit_radius"].AsDouble();for(int i=0;i<count;i++){long id=next+i;double a=random(id*3+1),b=random(id*3+2),c=random(id*3+3);var radial=tangent*(float)(Math.Cos(a*Math.Tau)*Math.Sqrt(b))+bitangent*(float)(Math.Sin(a*Math.Tau)*Math.Sqrt(b));var offset=radial*(float)radius;switch(Get(values,"fluid_emit_shape",0).AsInt32()){case 1:offset=new Vector3((float)(a-.5),(float)(b-.5),(float)(c-.5))*(float)(2*radius);break;case 2:offset=new Vector3((float)(a-.5),(float)(b-.5),(float)(c-.5)).Normalized()*(float)(Math.Pow(random(id*3+4),1.0/3)*radius);break;}int index=length+i;points[index]=pose*offset;velocities[index]=velocity+pose.Basis*((axis+radial*values["fluid_spread"].AsSingle()).Normalized()*values["fluid_emit_speed"].AsSingle());ids[index]=(int)id;masses[index]=(float)(values["fluid_density"].AsDouble()*Math.Pow(values["spacing"].AsDouble(),3));density[index]=1;}state["points"]=points;state["velocities"]=velocities;state["fluid_ids"]=ids;state["fluid_masses"]=masses;state["fluid_foam"]=foam;state["fluid_density"]=density;state["fluid_next_id"]=next+count;state["fluid_emitted"]=state["fluid_emitted"].AsInt64()+count;
    }
    private static T[] Resize<T>(T[] values,int count){Array.Resize(ref values,count);return values;}
    private static (int[][] Neighbors,long Checks) FindNeighbors(Vector3[] points,double h){var grid=new Dictionary<Vector3I,List<int>>();var cells=new Vector3I[points.Length];for(int i=0;i<points.Length;i++){var point=points[i];var cell=new Vector3I((int)Math.Floor(point.X/h),(int)Math.Floor(point.Y/h),(int)Math.Floor(point.Z/h));cells[i]=cell;if(!grid.TryGetValue(cell,out var list))grid[cell]=list=new List<int>();list.Add(i);}var output=new int[points.Length][];long checks=0;for(int i=0;i<points.Length;i++){var near=new List<int>();var cell=cells[i];for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(grid.TryGetValue(cell+new Vector3I(x,y,z),out var list))foreach(int j in list){checks++;if(j!=i&&points[i].DistanceSquaredTo(points[j])<h*h&&near.Count<128)near.Add(j);}output[i]=near.ToArray();}return(output,checks);}
    public Settings neighbors(Vector3[] points,double h){var result=FindNeighbors(points,h);var output=new GArray();foreach(var list in result.Neighbors)output.Add(list);return new Settings{["neighbors"]=output,["checks"]=result.Checks};}
    public double kernel(double distanceSquared,double h){double q=Math.Max(0,1-distanceSquared/(h*h));return 315/(64*Math.PI*h*h*h)*q*q*q;}
    public Vector3 gradient(Vector3 delta,double h){double distance=delta.Length();if(distance<.000001||distance>=h)return Vector3.Zero;return delta*(float)(-45/(Math.PI*Math.Pow(h,4))*Math.Pow(1-distance/h,2)/distance);}
}
